C++ Example demonstrating RVO/NRVO and its implications:

```cpp
class MyClass {
public:
  MyClass() { std::cout << "Constructor called\n"; }
  MyClass(const MyClass& other) { std::cout << "Copy constructor called\n"; }
  MyClass(MyClass&& other) { std::cout << "Move constructor called\n"; }
  ~MyClass() { std::cout << "Destructor called\n"; }
};

MyClass createMyClass() {
  MyClass obj;
  return obj; // RVO/NRVO likely to occur here
}

int main() {
  MyClass myObject = createMyClass();
  return 0;
}
```
